// ?GadgetTextEntrySetCursorPosition@@YAXPAVGameWindow@@I@Z
// partial score=0.4421 date=2026-10-14
// cl: /DNDEBUG /MD /EHsc

// Retail 0x004BE210 (ILT 0x000148A8) moves a text entry's cursor and scrolls
// the first visible character so the cursor stays inside the window.  Called
// by the matched GadgetTextEntryInsertCharacter (0x004BE9C0) and by
// GadgetTextEntryInput.  BFME EntryData keeps the cursor at +0x1c and the
// first visible character at +0x24; the ZH header layout does not apply, so
// the view stays local until the BFME gadget header is reconstructed.

typedef unsigned int UnsignedInt;
typedef int Int;

class GameWindow
{
public:
	Int winGetSize( Int *width, Int *height );
	void *winGetUserData();
};

// Display string view: slot 3 is getTextLength, slot 16 returns the pixel
// width of the text up to a character index (meaning unproven, opaque name).
class BfmeCursorText
{
public:
	virtual void slot00();
	virtual void slot01();
	virtual void slot02();
	virtual Int getTextLength();
	virtual void slot04();
	virtual void slot05();
	virtual void slot06();
	virtual void slot07();
	virtual void slot08();
	virtual void slot09();
	virtual void slot10();
	virtual void slot11();
	virtual void slot12();
	virtual void slot13();
	virtual void slot14();
	virtual void slot15();
	virtual Int slot16( Int charPos );
};

struct BfmeCursorEntryData
{
	BfmeCursorText *text;
	unsigned char padding04[0x18];
	unsigned short charPos;
	unsigned short conCharPos;
	unsigned char padding20[4];
	Int firstVisible;
};

template <class T> inline const T &bfmeMin( const T &a, const T &b )
{
	return ( a < b ) ? a : b;
}

void __cdecl GadgetTextEntrySetCursorPosition( GameWindow *window, UnsignedInt pos )
{
	BfmeCursorEntryData *e = (BfmeCursorEntryData *)window->winGetUserData();
	unsigned short cursor = (unsigned short)pos;
	e->charPos = cursor;
	if( (UnsignedInt)cursor < (UnsignedInt)e->firstVisible )
	{
		e->firstVisible = ( cursor < 5 ) ? 0 : cursor - 5;
		return;
	}

	Int width, height;
	window->winGetSize( &width, &height );
	if( width > 8 )
		width -= 8;

	BfmeCursorText *text = e->text;
	if( text->slot16( e->charPos ) - text->slot16( e->firstVisible ) > width )
	{
		Int len = e->text->getTextLength();
		Int endWidth = e->text->slot16( bfmeMin( e->charPos + 5, len ) );
		while( endWidth - e->text->slot16( e->firstVisible ) > width )
			e->firstVisible++;
	}
}
